"""Reconstruct the new certificates from the pinned public inputs and rerun the integer checks."""
import argparse
import gzip
import hashlib
import json
import math
import subprocess
import sys
import tempfile
from concurrent.futures import ThreadPoolExecutor
from fractions import Fraction as F
from pathlib import Path

if hasattr(sys, 'set_int_max_str_digits'):
    sys.set_int_max_str_digits(50000)

HERE = Path(__file__).resolve().parent
PINNED = '21d944c43098e2261ab7d713cd10f02a5eb13f3d'


def source_measure(base, spec):
    if 'input_member' in spec:
        from zipfile import ZipFile
        with ZipFile(base/spec['input']) as archive:data=archive.read(spec['input_member'])
    else:
        data = (base / spec['input']).read_bytes()
    assert hashlib.sha256(data).hexdigest() == spec['input_sha256']
    old = json.loads(gzip.decompress(data))
    for step in [*spec.get('preliminary_transforms', []), spec]:
        old = transform(old, step)
    return old


def mapped_coordinate(value,start,side,mode):
    """Map the two board edges to their new locations using exact rational coordinates."""
    x=F(value)
    if mode in ('center1','center2','center3','edges1','edges2','edges3'):
        width=F(int(mode[-1]))
        assert 2*width<min(start,side)
        if mode.startswith('center'):
            if x<=width:return x
            if x>=start-width:return x+side-start
            return width+(x-width)*(side-2*width)/(start-2*width)
        edge=width+(side-start)/2
        assert edge>0
        if x<=width:return x*edge/width
        if x>=start-width:return side-(start-x)*edge/width
        return x+(side-start)/2
    assert mode in ('uniform','linear','phase','hybrid')
    linear=x*side/start
    if mode in ('uniform','linear') or int(start)!=int(side) or start.denominator==1:return linear
    t,a,b=x-int(x),start-int(start),side-int(side)
    phase=int(x)+(t*b/a if t<=a else b+(t-a)*(1-b)/(1-a))
    return phase if mode=='phase' else (linear+phase)/2


def split_phase_rectangles(old,side,total):
    """Push a rectangular density through the phase map, splitting at every change of slope."""
    from collections import defaultdict
    from functools import lru_cache
    start=F(old['L']);phase=start-int(start);scale=total/F(old['total_mass'])
    knots=sorted({j+v for j in range(int(start)+1) for v in (F(0),phase) if 0<j+v<start})
    @lru_cache(None)
    def mapping(x):return mapped_coordinate(x,start,side,'phase')
    @lru_cache(None)
    def parts(a,b):
        marks=[a,*(v for v in knots if a<v<b),b]
        return tuple((mapping(x),mapping(y),(y-x)/(b-a)) for x,y in zip(marks,marks[1:]))
    masses=defaultdict(F)
    for row in old['rectangles']:
        x,y,X,Y=map(F,row['rectangle']);weight=F(row['mass'])*scale
        for a,A,fx in parts(x,X):
            for b,B,fy in parts(y,Y):
                masses[a,b,A,B]+=weight*fx*fy
    assert sum(masses.values(),F(0))==total
    return [dict(rectangle=list(map(str,box)),mass=str(mass)) for box,mass in sorted(masses.items()) if mass]


def transform(old, spec):
    if spec['warp']=='period_cells':
        from period_cells import change_density
        return change_density(old,spec['recipe'])
    start, side, total = F(old['L']), F(spec['side']), F(spec['mass'])
    factor = total / F(old['total_mass'])
    if spec['warp']=='phase_split':
        return dict(n=spec['n'],L=str(side),total_mass=str(total),points=[],rectangles=split_phase_rectangles(old,side,total))
    def coordinate(v):
        return str(mapped_coordinate(v,start,side,spec['warp']))
    from functools import lru_cache
    coord = lru_cache(None)(coordinate)
    rectangles = [dict(rectangle=[coord(x) for x in r['rectangle']], mass=str(F(r['mass'])*factor)) for r in old['rectangles']]
    return dict(n=spec['n'], L=str(side), total_mass=str(total), points=[], rectangles=rectangles)


def angle_jobs(measure, ranges, header, complete=True):
    intervals = []
    jobs = []
    for key, runs in ranges.items():
        k = int(key)
        assert k > 0
        step = F(83, 200*k)
        for a,b in runs:
            assert 0 <= a <= b <= k
            for r in range(a,b+1):
                intervals.append((max(F(0),(r-F(1,2))*step), (r+F(1,2))*step))
                jobs.append((k,r,header(k,r)))
    end = F(0)
    for left,right in sorted(intervals):
        if complete:assert left <= end
        end = max(end,right)
    if complete:assert end*end+2*end >= 1 and jobs
    return jobs


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--base', type=Path, required=True, help='lower_bounds_2026_11_19 at the pinned public commit')
    p.add_argument('--n', type=int)
    p.add_argument('--counts',type=int,nargs='+',help='verify a group of square counts')
    p.add_argument('--workers', type=int, default=4)
    p.add_argument('--inputs-only', action='store_true', help='diagnostic: check inputs and transfers without replaying new orientations')
    p.add_argument('--replay-existing', action='store_true', help='also recompute all previously published source checks')
    args = p.parse_args()
    if not __debug__ or args.workers < 1:
        p.error('Use Python with assertions enabled and a positive worker count.')
    base=args.base.resolve(); proof=base/'proof'
    for folder in (proof,base/'followup/envelopes',base/'followup/repeated',HERE):
        sys.path.insert(0,str(folder))
    import check
    from scaled_period import verify_periodic
    from transfer import source_grid,verify_geometry
    pack=json.loads((HERE/'certificate.json').read_text())
    assert hashlib.sha256((proof/'gram.cpp').read_bytes()).hexdigest()==pack['kernel_sha256']
    for r in pack['claims']:
        delta=F(r['side'])-F(r['previous_upper_endpoint'])
        assert delta>0
        if 'increase'in r:assert F(r['increase'])==delta
        else:r['increase']=str(delta)
    selected=[r for r in pack['claims'] if (args.n is None or r['n']==args.n) and (args.counts is None or r['n'] in args.counts)]
    if args.counts is not None:assert {r['n'] for r in selected}==set(args.counts)
    assert selected and len({r['n'] for r in selected})==len(selected)
    with tempfile.TemporaryDirectory() as tmp:
        temp=Path(tmp);binary=temp/'gram'
        if not args.inputs_only:
            subprocess.run(['c++','-O3','-std=c++17',proof/'gram.cpp','-o',binary],check=True)
        def replay(raw,jobs,executable=None):
            if args.inputs_only:return
            grid=temp/'rectangles';grid.write_bytes(raw)
            def one(item):
                k,r,h=item;f=temp/f'h_{k}_{r}';f.write_text(' '.join(map(str,h)))
                out=subprocess.run([executable or binary,grid,f,'2200000'],capture_output=True,text=True,check=True).stdout.split()
                assert out[0]=='PASS' and int(out[-1])>=check.bm.M
            with ThreadPoolExecutor(args.workers) as ex:list(ex.map(one,jobs))
        for key in sorted({r['source'] for r in selected}):
            spec=pack['sources'][key]
            if 'family_spec' in spec:
                from family_cut import verify as verify_family
                description=spec['family_spec'];assert key=='family_'+str(description['interval'])
                verify_family(base/'corners',description,[r for r in selected if r['source']==key])
                continue
            if 'registered_input' in spec:
                from registered_transfer import load,prove
                origin=spec['registered_input'];assert origin['input_sha256'].startswith(key)
                primary=load(origin)
                def edges(measure,r):
                    from boundary import verify_compact
                    verify_compact(pack['boundaries'][r['boundary']],measure,r,check,replay,angle_jobs)
                for row in selected:
                    if row['source']==key:prove(*primary,row,edges)
                continue
            if 'certificate_archive' in spec:
                from edge_reserve import check_rows, SOURCE_SHA, SOURCE_PATH
                assert spec['certificate_archive']==SOURCE_PATH and spec['archive_sha256']==SOURCE_SHA
                def check_archived_boundary(measure,row):
                    import boundary
                    boundary.verify_compact(pack['boundaries'][row['boundary']],measure,row,check,replay,angle_jobs)
                check_rows(base/SOURCE_PATH,[r for r in selected if r['source']==key],
                           replay_existing=args.replay_existing and not args.inputs_only,workers=args.workers,
                           boundary_checker=check_archived_boundary,replay_new=not args.inputs_only)
                continue
            if 'certificate_folder' in spec:
                folder=base/spec['certificate_folder'];m=check.verify(folder);measure,_=check.read_level(folder,m['levels'][0]);assert m['levels'][0]['measure_sha256'].startswith(key)
                if args.replay_existing and not args.inputs_only:
                    subprocess.run([sys.executable,proof/'replay.py',folder,'--controls','--workers',str(args.workers)],check=True)
            else:
                measure=source_measure(base,spec);raw=check.input_bytes(list(check.bm.rows(measure)));assert hashlib.sha256(raw).hexdigest()==spec['integer_grid_sha256']
                def header(k,r):
                    d=F(83,200*k);level=dict(measure,B=str(1/(1+d/(1-d*d/4))-F(1,10**12)),proof_net=dict(last=k,step=str(d)))
                    return check.header(level,r,'octagon-gram')
                jobs=angle_jobs(measure,spec['angles'],header)
                executable=None
                if spec.get('kernel')=='octagon':
                    assert hashlib.sha256((proof/'octagon.cpp').read_bytes()).hexdigest()==spec['kernel_sha256']
                    executable=temp/'octagon'
                    if not args.inputs_only and not executable.exists():subprocess.run(['c++','-O3','-std=c++17',proof/'octagon.cpp','-o',executable],check=True)
                replay(raw,jobs,executable)
                print(f"{key}: {len(jobs)} angular intervals",flush=True)
            grids={};periods={};repairs={}
            for row in (r for r in selected if r['source']==key):
                n,T=row['n'],F(row['side']);prior=F(row['previous_upper_endpoint']);assert T>prior and T-prior==F(row['increase'])
                target_n = n
                if 'inherited_from_count' in row:
                    n = row['inherited_from_count']
                    assert type(n) is int and 0 < n < target_n
                    row = dict(row, n=n)
                use=measure;repair=row.get('repair')
                if repair:
                    from local_corner import prepare,header as local_header
                    if repair not in repairs:
                        local=pack['repairs'][repair];p=local['parameters'];source_for_repair=measure
                        assert p.get('extension')==row.get('extension_before_repair')
                        if 'extension' in p:
                            from extend_measure import extend_measure
                            source_for_repair=extend_measure(measure,**p['extension'])
                        modified,raw,low=prepare(source_for_repair,p)
                        assert hashlib.sha256(raw).hexdigest()==p['integer_grid_sha256']
                        from local_corner import check_angular_union,inherited_grid
                        extra=local.get('inherited_angles',{})
                        jobs=angle_jobs(modified,local['angles'],lambda k,r:local_header(modified,low,k,r),not extra)
                        if jobs:replay(raw,jobs)
                        angles=[(k,r)for k,r,h in jobs]
                        for value,ranges in extra.items():
                            bigger,data,limit=inherited_grid(source_for_repair,p,value)
                            old=angle_jobs(bigger,ranges,lambda k,r:local_header(bigger,limit,k,r),False)
                            replay(data,old);angles.extend((k,r)for k,r,h in old)
                        check_angular_union(angles);repairs[repair]=modified
                    use=repairs[repair]
                if row['method'] in ('direct','monotonicity'):
                    assert T==F(use['L']) and F(use['total_mass'])==F(row['mass'])<n and (repair or measure['n']<=n)
                elif row['method']=='native_reserve':
                    from edge_reserve import verify_native
                    verify_native(use,row)
                elif row['method']=='seam':
                    from seam_lift import verify_seam
                    verify_seam(use,row)
                elif row['method']=='derived_boundary':
                    from derived_boundary import measure as derived_measure
                    import boundary
                    params=pack['repairs'][repair]['parameters'] if repair else None
                    owner=derived_measure(measure,use,params,row['foundation'])
                    boundary.verify_compact(pack['boundaries'][row['boundary']],owner,row,check,replay,angle_jobs)
                elif row['method'] in ('boundary','periodic_boundary'):
                    import boundary
                    basis=boundary.original_claim(row);part=('boundary',row['boundary'])
                    assert boundary.identity(basis)==row['boundary'] and basis['base_n']==use['n']
                    if part not in grids:
                        extra=pack['boundaries'][row['boundary']]
                        boundary.verify_compact(extra,use,basis,check,replay,angle_jobs)
                        grids[part]=True
                    if row['method']=='periodic_boundary':verify_periodic(boundary.padded_measure(use,basis),row,periods.setdefault(part,{}))
                elif row['method']=='copied_crop':
                    from extend_measure import copied_measure
                    params=pack['repairs'][repair]['parameters']
                    target_key=(repair,row['target_offset'])
                    if target_key not in grids:
                        target=copied_measure(measure,params,use,row['target_offset'],row['periods'])
                        grids[target_key]=(target,source_grid(target))
                    verify_geometry(grids[target_key][0],dict(row,method='crop',offset=0,periods=0),grids[target_key][1])
                elif row['method']=='corner_copy':
                    from extend_measure import copied_corner_mass
                    assert repair and T==(F(measure['L'])+row['target_offset'])*F(row.get('board_scale','1'))
                    assert F(pack['repairs'][repair]['parameters'].get('board_scale','1'))==F(row.get('board_scale','1'))
                    value=copied_corner_mass(measure,pack['repairs'][repair]['parameters'],row['target_offset'],row.get('periods'))
                    assert value==F(row['mass'])<n
                elif row['method']=='periodic':
                    verify_periodic(use,row,periods.setdefault(repair, {}))
                else:
                    if repair not in grids:grids[repair]=source_grid(use)
                    verify_geometry(use,row,grids[repair],{})
                print(f's({target_n}) >= {T} ({float(T):.10f})',flush=True)
    print(('Input and transfer check only' if args.inputs_only else 'Full new orientation replay complete')+f' for {len(selected)} square counts.',flush=True)

if __name__=='__main__':
    main()

