"""Tighten the worst half-angle gaps of the archived point, segment and rectangle proofs."""
from fractions import Fraction as F
from hashlib import sha256
from math import ceil,floor,isqrt
from pathlib import Path
import gzip,importlib.util,json,subprocess,sys

G=2**30
M=2**48


def original(root,n):
    # Load from this exact pinned archive even if another checker is named verify.
    folder=root/'mixed';sys.path.insert(0,str(folder/'code'))
    spec=importlib.util.spec_from_file_location('prior_mixed_angles',folder/'verify.py')
    old=importlib.util.module_from_spec(spec);spec.loader.exec_module(old)
    result=old.result(n)
    L,B,step,last=old.linear.source_parameters(n)
    angles={i*step for i in range(last+1)}
    for f in (folder/'evidence').glob(f'n{n}_*/meta.json'):
        meta=json.loads(f.read_text())
        with gzip.open(f.parent/'directions.jsonl.gz','rt')as rows:
            angles.update(F(meta['step'])*q['r']for q in map(json.loads,rows))
    grid=old.integer_rows(n,12,F(1)).encode()
    assert sha256(grid).hexdigest()==meta['input_sha256'] and sha256((folder/'code/mixedproj.cpp').read_bytes()).hexdigest()==meta['cpp_sha256']
    assert squared(L,B,angles)==F(result['lower_squared'])
    return L,B,angles,grid


def gaps(angles):
    ordered=sorted(angles);assert ordered[0]==0
    last=next(i for i,t in enumerate(ordered)if t*t+2*t>=1)
    return sorted([((b-a)/(1+a*b),a,b)for a,b in zip(ordered[:last],ordered[1:last+1])],reverse=True)


def squared(L,B,angles):
    g=gaps(angles)[0][0]
    return (L/(B*(1+g)))**2*(1+g*g)


def side(L,B,angles):
    sq=squared(L,B,angles);d=10**18
    return F(isqrt(sq.numerator*d*d//sq.denominator),d)


def header(L,B,t):
    a,b=t.numerator,t.denominator;c=b*b-a*a;s=2*a*b;e=b*b+a*a
    low=floor(L*G/2);high=ceil((L-B*F(c+s,2*e))*G)
    return [c,s,e,floor(B*G/2),low,high,low,high]


def compile_kernel(root,dest,grid):
    dest.mkdir(exist_ok=True,parents=True)
    (dest/'grid').write_bytes(grid)
    subprocess.run(['c++','-O3','-std=c++17',root/'mixed/code/mixedproj.cpp','-o',dest/'check'],check=True)


def native(dest,h,cap):
    fp=dest/'direction';fp.write_text(' '.join(map(str,h))+'\n')
    result=subprocess.run([dest/'check',dest/'grid',fp,str(cap)],capture_output=True,text=True)
    w=result.stdout.split();assert len(w)==6 and w[0]in ('PASS','UNDECIDED'),(result.returncode,result.stderr[:200])
    return [w[0],*map(int,w[1:])]


def options(a,b):
    return [((a+b)/2).limit_denominator(18000),((2*a+b)/3).limit_denominator(22000),
            ((a+2*b)/3).limit_denominator(26000),((3*a+b)/4).limit_denominator(32000),
            ((a+3*b)/4).limit_denominator(34000)]


def recipe(old,extra):
    import heapq
    heap=[(-g,a,b)for g,a,b in gaps(old)];heapq.heapify(heap)
    indices=[]
    for t in extra:
        _,a,b=heapq.heappop(heap)
        t=F(t);choices=options(a,b);i=choices.index(t);assert a<t<b
        if indices and indices[-1][0]==i:indices[-1][1]+=1
        else:indices.append([i,1])
        for l,r in [(a,t),(t,b)]:heapq.heappush(heap,(-(r-l)/(1+l*r),l,r))
    return indices


def expand(old,runs):
    import heapq
    heap=[(-g,a,b)for g,a,b in gaps(old)];heapq.heapify(heap)
    for i,k in runs:
        assert 0<=i<5 and 0<k<=80000
        for _ in range(k):
            _,a,b=heapq.heappop(heap);t=options(a,b)[i];assert a<t<b
            yield str(t),None
            for l,r in [(a,t),(t,b)]:heapq.heappush(heap,(-(r-l)/(1+l*r),l,r))


def verify(root,rows,replay=False):
    from tempfile import TemporaryDirectory
    from edge_reserve import SOURCE_SHA
    cases={}
    for row in rows:cases.setdefault(row['base_n'],[]).append(row)
    for n,group in cases.items():
        L,B,old,grid=original(root,n)
        with TemporaryDirectory()as tmp:
            d=Path(tmp)
            if replay:compile_kernel(root,d,grid)
            seen={}
            for row in group:
                assert row['case']=='mixed_'+str(n) and row['source']==SOURCE_SHA[:16] and n<=row['n']<325
                angles=set(old)
                mass=F(json.loads(gzip.decompress((root/'linear/evidence'/f'n{n}'/'candidate.json.gz').read_bytes()))['total_mass'])
                assert mass==F(row['mass'])<n
                extra=expand(old,row['angle_recipe']) if 'angle_recipe' in row else row['additional_angles']
                for ts,receipt in extra:
                    t=F(ts);assert 0<t<1 and t not in angles
                    h=header(L,B,t)
                    if receipt is not None:
                        verdict,nodes,leaves,terms,depth,lower=receipt
                        assert verdict=='PASS' and nodes>0 and leaves>0 and terms>=0 and 0<=depth<=66 and lower>=M
                    if replay and t not in seen:seen[t]=native(d,h,receipt[1]+32 if receipt else 16000000)
                    if replay:
                        assert seen[t][0]=='PASS' and seen[t][-1]>=M
                        if receipt is not None:assert seen[t]==receipt
                    angles.add(t)
                T=side(L,B,angles);prior=F(row['previous_upper_endpoint'])
                assert T==F(row['side'])>prior and T-prior==F(row['increase'])
                print(f"s({row['n']}) >= {T} ({float(T):.14f}), additional mixed-measure directions",flush=True)

